-- 004: additive source-only browser authority schema. Never executed by this change.
CREATE TABLE IF NOT EXISTS txo_fabric_browser_bindings (binding_id uuid PRIMARY KEY,issuer varchar(1024) NOT NULL,audience varchar(1024) NOT NULL,oidc_subject varchar(255) NOT NULL,upstream_user_reference varchar(255) NOT NULL,tenant_key varchar(63) NOT NULL,fabric_tenant_id varchar(64) NOT NULL,tenant_bundle_uid uuid NOT NULL,fabric_user_id varchar(35) NOT NULL,binding_version bigint NOT NULL,state varchar(24) NOT NULL,created_at_ms bigint NOT NULL,updated_at_ms bigint NOT NULL,revoked_at_ms bigint,superseded_at_ms bigint,tombstoned_at_ms bigint,bootstrap_reference_digest varchar(43),bootstrap_expires_at_ms bigint,CONSTRAINT browser_binding_version CHECK(binding_version>0),CONSTRAINT browser_binding_state CHECK(state IN ('bootstrap_pending','active','superseded','revoked','tombstoned')),CONSTRAINT browser_binding_identity CHECK(length(issuer)>0 AND length(audience)>0 AND length(oidc_subject)>0 AND length(upstream_user_reference)>0),CONSTRAINT browser_binding_pending CHECK((state='bootstrap_pending' AND bootstrap_reference_digest IS NOT NULL AND length(bootstrap_reference_digest)=43 AND bootstrap_expires_at_ms>created_at_ms) OR (state<>'bootstrap_pending' AND bootstrap_reference_digest IS NULL AND bootstrap_expires_at_ms IS NULL)),CONSTRAINT browser_binding_times CHECK(updated_at_ms>=created_at_ms));
CREATE UNIQUE INDEX IF NOT EXISTS browser_binding_active_identity ON txo_fabric_browser_bindings(issuer,audience,oidc_subject) WHERE state='active';
CREATE UNIQUE INDEX IF NOT EXISTS browser_binding_active_user ON txo_fabric_browser_bindings(tenant_bundle_uid,fabric_user_id) WHERE state='active';
CREATE UNIQUE INDEX IF NOT EXISTS browser_binding_identity_version ON txo_fabric_browser_bindings(issuer,audience,oidc_subject,binding_version);
CREATE UNIQUE INDEX IF NOT EXISTS browser_binding_user_version ON txo_fabric_browser_bindings(tenant_bundle_uid,fabric_user_id,binding_version);
CREATE TABLE IF NOT EXISTS txo_fabric_client0_bootstrap_consumptions (proof_digest varchar(43) PRIMARY KEY,binding_id uuid UNIQUE NOT NULL REFERENCES txo_fabric_browser_bindings(binding_id) ON DELETE RESTRICT,authority_version varchar(128) NOT NULL,consumed_at_ms bigint NOT NULL);
CREATE TABLE IF NOT EXISTS txo_fabric_browser_session_capabilities (session_digest varchar(43) PRIMARY KEY REFERENCES txo_fabric_webui_sessions(session_digest) ON DELETE RESTRICT,binding_id uuid NOT NULL REFERENCES txo_fabric_browser_bindings(binding_id) ON DELETE RESTRICT,binding_version bigint NOT NULL,state varchar(16) NOT NULL,issued_at_ms bigint NOT NULL,expires_at_ms bigint NOT NULL,revoked_at_ms bigint,CONSTRAINT browser_capability_state CHECK(state IN ('active','revoked','expired','superseded')),CONSTRAINT browser_capability_times CHECK(expires_at_ms>issued_at_ms));
CREATE INDEX IF NOT EXISTS browser_capability_binding ON txo_fabric_browser_session_capabilities(binding_id,binding_version,state,expires_at_ms);
CREATE TABLE IF NOT EXISTS txo_fabric_bound_chat_threads (thread_id varchar(40) PRIMARY KEY,binding_id uuid NOT NULL REFERENCES txo_fabric_browser_bindings(binding_id) ON DELETE RESTRICT,binding_version bigint NOT NULL,tenant_key varchar(63) NOT NULL,fabric_tenant_id varchar(64) NOT NULL,tenant_bundle_uid uuid NOT NULL,fabric_user_id varchar(35) NOT NULL,agent_key varchar(56) NOT NULL,agent_identity_uid uuid NOT NULL,agent_observed_generation bigint NOT NULL,remote_session_id varchar(128),created_at_ms bigint NOT NULL,updated_at_ms bigint NOT NULL,lease_token varchar(32),lease_expires_at_ms bigint,lease_uncertain boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS bound_thread_continuity ON txo_fabric_bound_chat_threads(binding_id,binding_version,tenant_bundle_uid,fabric_user_id,agent_key,agent_identity_uid,agent_observed_generation);
CREATE UNIQUE INDEX IF NOT EXISTS bound_thread_remote_once ON txo_fabric_bound_chat_threads(agent_identity_uid,remote_session_id) WHERE remote_session_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS txo_fabric_bound_chat_turns (thread_id varchar(40) NOT NULL REFERENCES txo_fabric_bound_chat_threads(thread_id) ON DELETE RESTRICT,turn_id varchar(32) NOT NULL,PRIMARY KEY(thread_id,turn_id));
-- Fixed, parameterized CAS boundary. It intentionally denies until separately qualified runtime composition supplies the durable procedure body.
CREATE OR REPLACE FUNCTION txo_complete_browser_authority_bootstrap(v_session_digest varchar,v_issuer varchar,v_audience varchar,v_subject varchar,v_upstream_reference varchar,v_tenant_key varchar,v_fabric_tenant_id varchar,v_tenant_bundle_uid varchar,v_fabric_user_id varchar,v_binding_version bigint,v_proof_digest varchar,v_consumed_at_ms bigint,v_authority_version varchar,v_now_ms bigint,v_session_expires_at_ms bigint) RETURNS TABLE(browser_session_handle varchar,binding_id varchar,binding_version bigint,state varchar,issued_at bigint,expires_at bigint) LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'browser authority persistence runtime is not enabled'; END; $$;
